29	Cli parse_cli(const std::vector<std::string>& args) {
30	  Cli c;
31	  if (args.empty()) return c;  // no subcommand; caller prints usage
32	
33	  // First token is the subcommand, unless it is a top-level help request.
34	  if (args[0] == "-h" || args[0] == "--help") {
35	    c.help = true;
36	    return c;
37	  }
38	  c.subcommand = args[0];
39	
40	  for (size_t i = 1; i < args.size(); ++i) {
41	    const std::string& a = args[i];
42	
43	    if (a == "--") {  // the passthrough boundary: rest is verbatim
44	      c.has_passthrough = true;
45	      for (size_t j = i + 1; j < args.size(); ++j) c.passthrough.push_back(args[j]);
46	      break;
47	    }
48	    if (a == "-h" || a == "--help") {
49	      c.help = true;
50	      continue;
51	    }
52	    if (a == "--dry-run") {
53	      c.dry_run = true;
54	      continue;
55	    }
56	    if (a == "--verify") {
57	      c.verify = true;
58	      continue;
59	    }
60	    if (a == "--cosim") {
61	      c.cosim = true;
62	      continue;
63	    }
64	    if (a == "--cosim-refine") {
65	      c.cosim_refine = true;
66	      continue;
67	    }
68	    if (a == "--gdb") {
69	      c.gdb = true;
70	      continue;
71	    }
72	
73	    const struct {
74	      const char* flag;
75	      std::string* out;
76	    } opts[] = {{"--model", &c.model},
77	                {"--engine", &c.engine},
78	                {"--trigger", &c.trigger},
79	                {"--what", &c.what},
80	                {"--pc-start", &c.pc_start},
81	                {"--pc-end", &c.pc_end},
82	                {"--qemu-icount", &c.qemu_icount},
83	                {"--vsim-icount", &c.vsim_icount},
84	                {"--mem-size", &c.mem_size},
85	                {"--mmap-size", &c.mem_size},  // retired spelling, same knob
86	                {"--vsim-warmup-icount", &c.vsim_warmup_icount},
87	                {"--cosim-interval", &c.cosim_interval},
88	                {"--cosim-max-records", &c.cosim_max_records},
89	                {"--kanata", &c.kanata},
90	                {"--objdump", &c.objdump},
91	                {"--gdb-port", &c.gdb_port}};
92	    bool consumed = false;
93	    for (const auto& o : opts) {
94	      int r = match_opt(args, i, o.flag, *o.out);
95	      if (r < 0) { c.error = std::string("missing value for ") + o.flag; return c; }
96	      if (r > 0) { consumed = true; break; }
97	    }
98	    if (consumed) continue;
99	
100	    if (a.size() > 1 && a[0] == '-') {
101	      c.error = "unknown option: " + a;
102	      return c;
103	    }
104	    c.positional.push_back(a);
105	  }
106	
107	  return c;
108	}
