110	Cli parse_cli(int argc, char** argv) {
111	  std::vector<std::string> args;
112	  args.reserve(argc > 1 ? static_cast<size_t>(argc - 1) : 0);
113	  for (int i = 1; i < argc; ++i) args.emplace_back(argv[i]);
114	  return parse_cli(args);
115	}
