58	// Validate the lone-ELF positional shape the standalone models require: print
59	// the diagnostic and return 2 on a violation, else 0. Split out so `cycle`
60	// can reject a missing/extra ELF BEFORE paying for engine discovery (which
61	// spawns a --describe subprocess per Verilator build). `model` labels the error.
62	int check_one_elf(const Cli& cli, const char* model) {
63	  if (cli.positional.empty()) {
64	    std::fprintf(stderr, "andes-sim run --model %s: missing ELF\n", model);
65	    return 2;
66	  }
67	  if (cli.positional.size() > 1) {
68	    std::fprintf(stderr,
69	                 "andes-sim run --model %s: unexpected argument '%s' "
70	                 "(engine args go after --)\n",
71	                 model, cli.positional[1].c_str());
72	    return 2;
73	  }
74	  return 0;
75	}
