99	// `run --model fast`: QEMU alone, functional, transparent passthrough. Needs
100	// only the built-in qemu descriptor, so it resolves that directly rather than
101	// discover_engines(), which would spawn a --describe subprocess per Verilator
102	// build only to discard them all here.
103	int run_fast(const Cli& cli) {
104	  // fast is QEMU-only; an explicit engine must name it.
105	  if (!cli.engine.empty() && cli.engine != "qemu") {
106	    std::fprintf(stderr,
107	                 "andes-sim run --model fast: engine must be 'qemu', got '%s'\n",
108	                 cli.engine.c_str());
109	    return 2;
110	  }
111	  // --mem-size forwards a plain `-m`; QEMU validates it (as-is, no mmap, no
112	  // default injected). It precedes the post-`--` args, so a user's own -m wins.
113	  std::string err;
114	  std::vector<std::string> extra = qemu_m_args(cli.mem_size, err);
115	  if (!err.empty()) {
116	    std::fprintf(stderr, "andes-sim run --model fast: %s\n", err.c_str());
117	    return 2;
118	  }
119	  // --gdb: inject QEMU's built-in GDB stub and pause at startup.
120	  if (cli.gdb) {
121	    const std::string port = cli.gdb_port.empty() ? "1234" : cli.gdb_port;
122	    extra.push_back("-gdb");
123	    extra.push_back("tcp::" + port);
124	    extra.push_back("-S");
125	  }
126	  return run_standalone(cli, builtin_qemu(), "fast", extra);
127	}
