132	// Block until 127.0.0.1:`port` is LISTENing (or `timeout_ms` elapses). vsim opens
133	// its --jtag-port only after it has reset and halted the hart, so the debugger we
134	// exec next must not race ahead of it -- OpenOCD/ICEman do not retry the bitbang
135	// connect, and a missed connect leaves the session dead. Non-intrusive: scans
136	// /proc/net/tcp rather than connecting (a probe connection would land in vsim's
137	// single debugger slot). Returns false on timeout.
138	static bool wait_for_jtag_port(uint16_t port, int timeout_ms = 20000) {
139	  constexpr int kPollMs = 50;
140	  for (int waited = 0; waited <= timeout_ms; waited += kPollMs) {
141	    if (std::FILE* f = std::fopen("/proc/net/tcp", "re")) {
142	      char line[512];
143	      while (std::fgets(line, sizeof line, f)) {
144	        // cols: sl  local_address(IP:port hex)  rem_address  st  ...
145	        // "%*8x:%x" skips the 8-hex-digit IPv4 and reads the local port; the
146	        // 0A (TCP_LISTEN) filter also drops the non-hex header row.
147	        unsigned lport = 0, st = 0;
148	        if (std::sscanf(line, "%*s %*8x:%x %*s %x", &lport, &st) == 2
149	            && st == 0x0A && lport == port) {
150	          std::fclose(f);
151	          return true;
152	        }
153	      }
154	      std::fclose(f);
155	    }
156	    std::this_thread::sleep_for(std::chrono::milliseconds(kPollMs));
157	  }
158	  return false;
159	}
