161	// `run --model cycle --gdb`: start vsim with --jtag-port 9104 and -S (halt at
162	// startup) in the background, then exec ICEman ($ICEMAN env var) with -Z v5 in
163	// the foreground.
164	int run_cycle_gdb(const Cli& cli, const EngineDescriptor& eng) {
165	  const char* iceman = std::getenv("ICEMAN");
166	  if (!iceman || !*iceman) {
167	    std::fprintf(stderr,
168	                 "andes-sim run --model cycle --gdb: $ICEMAN not set "
169	                 "(export ICEMAN=<path to ICEman binary>)\n");
170	    return 2;
171	  }
172	  // Build vsim argv from the standalone template, appending user passthrough
173	  // and the JTAG port flag.
174	  const std::string elf = abs_elf(cli.positional[0], "--model cycle --gdb");
175	  if (elf.empty()) return 2;
176	  const std::string jtag_port = cli.gdb_port.empty() ? "9104" : cli.gdb_port;
177	  std::vector<std::string> vsim_pass = cli.passthrough;
178	  vsim_pass.push_back("--jtag-port");
179	  vsim_pass.push_back(jtag_port);
180	  vsim_pass.push_back("-S");  // halt the hart at startup so the debugger attaches
181	                              // to a stopped core (--jtag-port alone free-runs)
182	  std::string err;
183	  const std::vector<std::string> vsim_argv =
184	      passthrough_argv(eng, "standalone", elf, vsim_pass, err);
185	  if (!err.empty()) {
186	    std::fprintf(stderr, "andes-sim run --model cycle --gdb: %s\n", err.c_str());
187	    return 2;
188	  }
189	  std::fprintf(stderr,
190	               "[andes-sim] --gdb: vsim JTAG on port %s, exec ICEman\n",
191	               jtag_port.c_str());
192	  if (fork_background(vsim_argv) < 0) {
193	    std::fprintf(stderr,
194	                 "andes-sim run --model cycle --gdb: failed to fork vsim\n");
195	    return 1;
196	  }
197	  // with -S (passed above) vsim halts the hart before it opens the JTAG port, so
198	  // wait for the port before launching the debugger (it does not retry). Numeric
199	  // ports only; a non-numeric --gdb-port (atoi -> 0) skips the wait and lets the
200	  // engine reject it. Best-effort: warn but launch anyway if it never appears.
201	  if (const int pnum = std::atoi(jtag_port.c_str());
202	      pnum > 0 && !wait_for_jtag_port(static_cast<uint16_t>(pnum)))
203	    std::fprintf(stderr,
204	                 "[andes-sim] --gdb: warning: vsim JTAG port %s not LISTENing "
205	                 "after 20s; launching the debugger anyway\n",
206	                 jtag_port.c_str());
207	  return exec_passthrough({iceman, "-Z", "v5"});
208	}
