41	// Emit the andes-sim engine descriptor (see docs/engine_interface.md). This is
42	// the self-describe half of the framework's hot-plug contract: andes-sim runs
43	// `sim_<cfg> --describe`, parses this JSON, and can then drive the binary with
44	// no per-engine code. vlen/xlen come from the same embedded config.inc blob
45	// that --print-config dumps; the config name comes from VSIM_CPU_PYMODULE_NAME.
46	static void describe_engine()
47	{
48	  std::string cfg = VSIM_CPU_PYMODULE_NAME;  // "simulator_<cfg>"
49	  const std::string prefix = "simulator_";
50	  if (cfg.starts_with(prefix))
51	    cfg = cfg.substr(prefix.size());
52	
53	  const std::string_view blob(&_binary_config_inc_start,
54	                              static_cast<size_t>(&_binary_config_inc_end
55	                                                  - &_binary_config_inc_start));
56	  auto scan_int = [blob](std::string_view key) -> long {
57	    size_t pos = blob.find(key);
58	    if (pos == std::string_view::npos)
59	      return 0;
60	    pos += key.size();
61	    while (pos < blob.size() && (blob[pos] < '0' || blob[pos] > '9'))
62	      ++pos;
63	    long v = 0;
64	    while (pos < blob.size() && blob[pos] >= '0' && blob[pos] <= '9')
65	      v = v * 10 + (blob[pos++] - '0');
66	    return v;
67	  };
68	  const long vlen = scan_int("NDS_VLEN");
69	  const long dlen = scan_int("NDS_DLEN");
70	  const long elen = scan_int("NDS_ELEN");
71	  const long xlen = scan_int("NDS_XLEN");
72	
73	  // Built by hand (not fmt) to keep the literal {bin}/{elf}/{state_in}
74	  // placeholders out of fmt's brace parser.
75	  std::string json;
76	  json += "{\n";
77	  json += "  \"id\": \"verilator:" + cfg + "\",\n";
78	  json += "  \"type\": \"verilator\",\n";
79	  json += "  \"kind\": \"cycle-accurate\",\n";
80	  json += "  \"vlen\": " + std::to_string(vlen) + ", \"dlen\": "
81	          + std::to_string(dlen) + ", \"elen\": " + std::to_string(elen)
82	          + ", \"xlen\": " + std::to_string(xlen) + ",\n";
83	  json += "  \"triggers\": [\"csr\", \"pc\", \"icount\"],\n";
84	  json += "  \"roles\": [\"standalone\", \"accurate-leg\"],\n";
85	  json += "  \"state\": [\"resume\", \"drain\"],\n";
86	  json += "  \"invoke\": {\n";
87	  json += "    \"standalone\": [\"{bin}\", \"{elf}\"],\n";
88	  json += "    \"accurate-leg\": [\"{bin}\", \"{elf}\", "
89	          "\"--resume-from-qemu\", \"{state_in}\", "
90	          "\"--handoff-out\", \"{state_out}\", "
91	          "\"--shared-mem-path\", \"{mmap}\", "
92	          "\"--shared-mem-size\", \"{mmap_size}\", "
93	          "\"--shared-mem-base\", \"{mmap_base}\"]\n";
94	  json += "  },\n";
95	  json += "  \"result\": \"stderr:cycles\"\n";
96	  json += "}\n";
97	  fwrite(json.data(), 1, json.size(), stdout);
98	}
