229	// cosim_redesign F3: parse the --hybrid-cosim-at colon-separated retire
230	// targets. Must be strictly ascending, each >= 1.
231	static auto parse_cosim_targets(const std::string& spec)
232	  -> std::vector<uint64_t>
233	{
234	  std::vector<uint64_t> targets;
235	  std::size_t pos = 0;
236	  while (pos <= spec.size()) {
237	    const auto colon = spec.find(':', pos);
238	    const auto tok = spec.substr(
239	      pos, colon == std::string::npos ? std::string::npos : colon - pos);
240	    try {
241	      std::size_t used = 0;
242	      const uint64_t v = std::stoull(tok, &used, 0);
243	      if (used != tok.size() || v == 0) throw std::invalid_argument(tok);
244	      targets.push_back(v);
245	    } catch (...) {
246	      throw std::runtime_error("--hybrid-cosim-at: bad target '" + tok
247	                               + "' in '" + spec + "'");
248	    }
249	    if (colon == std::string::npos) break;
250	    pos = colon + 1;
251	  }
252	  for (std::size_t i = 1; i < targets.size(); ++i)
253	    if (targets[i] <= targets[i - 1])
254	      throw std::runtime_error(
255	        "--hybrid-cosim-at: targets must be strictly ascending: " + spec);
256	  return targets;
257	}
