210	// `run --model cycle`: one cycle-accurate engine alone, from reset (no QEMU,
211	// no --resume-from-qemu), transparent passthrough -- cycles surface in the
212	// engine's own output. Unlike fast, this must discover the Verilator build(s)
213	// to resolve the engine (explicit --engine, else the sole one).
214	int run_accurate(const Cli& cli) {
215	  // Reject a missing/extra ELF before discovery so a CLI typo does not spawn a
216	  // --describe subprocess per Verilator build only to fail on the argument.
217	  if (int rc = check_one_elf(cli, "cycle")) return rc;
218	  // --mem-size is validated but has nothing to size: the cycle engine always
219	  // models its full DRAM window. Say so instead of silently ignoring it.
220	  if (!cli.mem_size.empty()) {
221	    std::string se;
222	    if (parse_size(cli.mem_size, se); !se.empty()) {
223	      std::fprintf(stderr, "andes-sim run --model cycle: --mem-size: %s\n",
224	                   se.c_str());
225	      return 2;
226	    }
227	    std::fprintf(stderr,
228	                 "[andes-sim] --mem-size: the cycle engine models its full "
229	                 "DRAM window; nothing to size\n");
230	  }
231	  Discovery disc = discover_engines();
232	  std::string err;
233	  const EngineDescriptor* eng =
234	      resolve_accurate_engine(disc.engines, cli.engine, err);
235	  if (!eng) {
236	    std::fprintf(stderr, "andes-sim run --model cycle: %s\n", err.c_str());
237	    // Surface why an expected engine may be absent (failed --describe, etc.).
238	    for (const std::string& w : disc.warnings)
239	      std::fprintf(stderr, "andes-sim: skipped engine: %s\n", w.c_str());
240	    return 2;
241	  }
242	  // --cosim on the cycle model = lock-step DV co-sim against a QEMU oracle,
243	  // not a plain standalone run.
244	  if (cli.cosim) return run_cosim_lockstep(cli, *eng);
245	  if (cli.gdb) return run_cycle_gdb(cli, *eng);
246	  return run_standalone(cli, *eng, "cycle");
247	}
