249	// Parse --cosim-max-records: empty => 0 (unbounded; the oracle runs to program
250	// exit and defines the record count). Returns false + sets err on a bad value.
251	bool parse_cosim_max(const std::string& s, unsigned long long& out,
252	                     std::string& err) {
253	  out = 0;
254	  if (s.empty()) return true;
255	  char* end = nullptr;
256	  out = std::strtoull(s.c_str(), &end, 10);
257	  if (!end || *end != '\0') {
258	    err = "--cosim-max-records: want a non-negative integer, got '" + s + "'";
259	    return false;
260	  }
261	  return true;
262	}
