264	// `run --model cycle --cosim`: lock-step DV co-sim (cosim_redesign F6, usage
265	// 1). Two independent boots of the same ELF -- the QEMU oracle (golden) and
266	// the vsim DUT -- each drain one full record per execution attempt from the
267	// arm pc; the streams are aligned by attempt index and diffed to localize the
268	// first diverging instruction. No handoff, no shared mmap. The oracle runs
269	// first (MHz-fast, defines the record count K); the DUT is then bounded to K
270	// so a diverged hart cannot run away.
271	int run_cosim_lockstep(const Cli& cli, const EngineDescriptor& eng) {
272	  auto fail = [](const std::string& msg) {
273	    std::fprintf(stderr, "andes-sim run --model cycle --cosim: %s\n",
274	                 msg.c_str());
275	    return 2;
276	  };
277	  if (int rc = check_one_elf(cli, "cycle")) return rc;
278	
279	  std::error_code ec;
280	  const fs::path elf = fs::absolute(cli.positional[0], ec);
281	  if (ec || !fs::is_regular_file(elf, ec))
282	    return fail("ELF not found: " + cli.positional[0]);
283	  const std::string elf_path = elf.string();
284	
285	  // Arm pc: --pc-start (symbol or 0x addr) overrides the ELF entry default.
286	  std::string err;
287	  uint64_t arm_pc = 0;
288	  if (cli.pc_start.empty()) {
289	    arm_pc = elf_entry(elf_path, err);
290	    if (!err.empty()) return fail(err);
291	  } else {
292	    const std::string hex = resolve_pc(elf_path, cli.pc_start, err);
293	    if (!err.empty()) return fail(err);
294	    arm_pc = std::strtoull(hex.c_str(), nullptr, 16);
295	  }
296	  char arm_buf[32];
297	  std::snprintf(arm_buf, sizeof(arm_buf), "0x%llx",
298	                static_cast<unsigned long long>(arm_pc));
299	
300	  unsigned long long max_records = 0;
301	  if (!parse_cosim_max(cli.cosim_max_records, max_records, err))
302	    return fail(err);
303	
304	  // Workdir for the two record streams (removed on exit).
305	  const fs::path wd =
306	      fs::temp_directory_path() /
307	      ("andes-cosim-ls-" + std::to_string(::getpid()));
308	  fs::create_directories(wd, ec);
309	  const std::string oracle_stream = (wd / "oracle.ckpts").string();

