16	public:
17	  using ahb_manager = ahb::manager<AddrWidth, DataWidth>;
18	  using addr_type = typename ahb_manager::addr_type;
19	  using data_type = typename ahb_manager::data_type;
20	
21	  SystemCDmiBus(ahb_manager& ahb, const sc_core::sc_time& cycle)
22	      : ahb_{ahb}, cycle_{cycle}
23	  {}
24	
25	  void write(uint8_t reg, uint32_t value) override
26	  {
27	    static_cast<void>(ahb_.write(addr_type(reg << 2), data_type(value)));
28	    drain();
29	  }
30	
31	  auto read(uint8_t reg) -> uint32_t override
32	  {
33	    ahb_.read(addr_type(reg << 2));
34	    drain();
35	    return uint32_t(ahb_.txn.data.to_uint64());
36	  }
37	
38	private:
39	  void drain()
40	  {
41	    while (ahb_.txn.is_busy()) sc_core::sc_start(cycle_);
42	    if (ahb_.txn.phase == ahb_manager::transaction::phase::error)
43	      throw std::runtime_error("SystemCDmiBus: DMI transaction error");
44	  }
45	
46	  ahb_manager& ahb_;
47	  sc_core::sc_time cycle_;
48	};
